/**
 * Physics Model Interface - Two-State Architecture
 *
 * The core insight is that there are only TWO movement states: ON_GROUND and IN_AIR.
 * Everything else (sliding, falling) emerges naturally from:
 *
 * - Surface angle vs ground threshold
 * - Velocity clipping against surfaces
 * - Different physics rules for ground vs air
 *
 * ```js
 * import { Physics } from '@three-blocks/pro';
 *
 * const CustomModel = {
 *   name: 'custom',
 *   config: { gravity: 20, maxSpeed: 10, groundAccel: 12, airAccel: 3, friction: 4, stopSpeed: 1, jumpVelocity: 10, groundAngleThreshold: 0.7854 },
 *   isGround( angle ) { return angle < this.config.groundAngleThreshold; },
 *   groundMove( velocity, wishDir, wishSpeed, delta ) { },
 *   airMove( velocity, wishDir, wishSpeed, delta ) { },
 *   clipVelocity( velocity, normal ) { },
 *   jump( velocity, onGround ) { if ( ! onGround ) return false; velocity.y = this.config.jumpVelocity; return true; },
 * };
 *
 * const physics = new Physics( { physicsModel: 'custom', customPhysicsModel: CustomModel } );
 * ```
 *
 * @module @three-blocks/pro/physics/models/PhysicsModel
 * @short Physics model interface and validation helpers.
 * @category Physics
 * @tags Presets, Movement, Physics
 */
/**
 * Physics model configuration - all the tunable parameters
 * @typedef {Object} PhysicsConfig
 * @property {number} gravity - Gravity strength (sv_gravity, e.g., 800)
 * @property {number} maxSpeed - Maximum movement speed (sv_maxspeed)
 * @property {number} groundAccel - Ground acceleration (sv_accelerate)
 * @property {number} airAccel - Air acceleration (sv_airaccelerate)
 * @property {number} friction - Ground friction (sv_friction)
 * @property {number} stopSpeed - Speed below which full stop applies (sv_stopspeed)
 * @property {number} jumpVelocity - Jump velocity
 * @property {number} groundAngleThreshold - Max angle (radians) for walkable ground (~0.785 = 45°)
 * @property {number} [airControl] - Air control factor 0-1 (optional)
 * @property {number} [overbounce] - clipVelocity overbounce factor (default 1.001)
 * @property {string} [sweepMode='none'] - Sweep movement mode for high-velocity tunneling prevention:
 *   - 'binary': BSP tracing - binary search along movement vector to find first collision
 *   - 'none': No sweep (default for slower movement)
 */
/**
 * Minimal body state - only essential information
 * @typedef {Object} BodyState
 * @property {boolean} onGround - Whether body is on walkable ground (determined by surface angle)
 * @property {boolean} hasContact - Whether body is touching any surface
 * @property {{x: number, y: number, z: number}} velocity - Current velocity
 * @property {{x: number, y: number, z: number}} wishDir - Input direction (normalized)
 * @property {{x: number, y: number, z: number}|null} surfaceNormal - Contact surface normal
 * @property {number} surfaceAngle - Contact surface angle from up (0 = flat, PI/2 = wall)
 * @property {number} wishSpeed - Desired speed from input magnitude
 */
/**
 * Physics Model Interface
 *
 * Each preset (Arcade, Platformer, Realistic) implements this interface.
 * The engine calls these methods in order during each physics step.
 *
 * @typedef {Object} PhysicsModel
 * @property {string} name - Unique identifier
 * @property {PhysicsConfig} config - Physics parameters
 * @property {function(number): boolean} isGround - Is surface angle walkable ground?
 * @property {function(THREE.Vector3, THREE.Vector3, number, number): void} groundMove - Ground physics
 * @property {function(THREE.Vector3, THREE.Vector3, number, number): void} airMove - Air physics (includes gravity)
 * @property {function(THREE.Vector3, THREE.Vector3): void} clipVelocity - Clip velocity against surface
 * @property {function(THREE.Vector3, boolean): boolean} jump - Handle jump input
 *
 * @property {function(THREE.Vector3, number): void} [clampVelocity] - Optional velocity clamping (default: 3D magnitude)
 * @property {function(THREE.Vector3, BodyState, number): void} [onPreStep] - Optional pre-step hook
 * @property {function(THREE.Vector3, BodyState, number): void} [onPostStep] - Optional post-step hook
 */
/**
 * Validates that an object conforms to the new PhysicsModel interface
 * @param {Object} model - The model to validate
 * @returns {boolean} - Whether the model is valid
 *
 * @example
 * import { validatePhysicsModel } from '@three-blocks/pro';
 * const ok = validatePhysicsModel( CustomModel );
 */
export function validatePhysicsModel(model: any): boolean;
/**
 * Physics model configuration - all the tunable parameters
 */
export type PhysicsConfig = {
    /**
     * - Gravity strength (sv_gravity, e.g., 800)
     */
    gravity: number;
    /**
     * - Maximum movement speed (sv_maxspeed)
     */
    maxSpeed: number;
    /**
     * - Ground acceleration (sv_accelerate)
     */
    groundAccel: number;
    /**
     * - Air acceleration (sv_airaccelerate)
     */
    airAccel: number;
    /**
     * - Ground friction (sv_friction)
     */
    friction: number;
    /**
     * - Speed below which full stop applies (sv_stopspeed)
     */
    stopSpeed: number;
    /**
     * - Jump velocity
     */
    jumpVelocity: number;
    /**
     * - Max angle (radians) for walkable ground (~0.785 = 45°)
     */
    groundAngleThreshold: number;
    /**
     * - Air control factor 0-1 (optional)
     */
    airControl?: number;
    /**
     * - clipVelocity overbounce factor (default 1.001)
     */
    overbounce?: number;
    /**
     * - Sweep movement mode for high-velocity tunneling prevention:
     * - 'binary': BSP tracing - binary search along movement vector to find first collision
     * - 'none': No sweep (default for slower movement)
     */
    sweepMode?: string;
};
/**
 * Minimal body state - only essential information
 */
export type BodyState = {
    /**
     * - Whether body is on walkable ground (determined by surface angle)
     */
    onGround: boolean;
    /**
     * - Whether body is touching any surface
     */
    hasContact: boolean;
    /**
     * - Current velocity
     */
    velocity: {
        x: number;
        y: number;
        z: number;
    };
    /**
     * - Input direction (normalized)
     */
    wishDir: {
        x: number;
        y: number;
        z: number;
    };
    /**
     * - Contact surface normal
     */
    surfaceNormal: {
        x: number;
        y: number;
        z: number;
    } | null;
    /**
     * - Contact surface angle from up (0 = flat, PI/2 = wall)
     */
    surfaceAngle: number;
    /**
     * - Desired speed from input magnitude
     */
    wishSpeed: number;
};
/**
 * Physics Model Interface
 *
 * Each preset (Arcade, Platformer, Realistic) implements this interface.
 * The engine calls these methods in order during each physics step.
 */
export type PhysicsModel = {
    /**
     * - Unique identifier
     */
    name: string;
    /**
     * - Physics parameters
     */
    config: PhysicsConfig;
    /**
     * - Is surface angle walkable ground?
     */
    isGround: (arg0: number) => boolean;
    /**
     * - Ground physics
     */
    groundMove: (arg0: THREE.Vector3, arg1: THREE.Vector3, arg2: number, arg3: number) => void;
    /**
     * - Air physics (includes gravity)
     */
    airMove: (arg0: THREE.Vector3, arg1: THREE.Vector3, arg2: number, arg3: number) => void;
    /**
     * - Clip velocity against surface
     */
    clipVelocity: (arg0: THREE.Vector3, arg1: THREE.Vector3) => void;
    /**
     * - Handle jump input
     */
    jump: (arg0: THREE.Vector3, arg1: boolean) => boolean;
    /**
     * - Optional velocity clamping (default: 3D magnitude)
     */
    clampVelocity?: (arg0: THREE.Vector3, arg1: number) => void;
    /**
     * - Optional pre-step hook
     */
    onPreStep?: (arg0: THREE.Vector3, arg1: BodyState, arg2: number) => void;
    /**
     * - Optional post-step hook
     */
    onPostStep?: (arg0: THREE.Vector3, arg1: BodyState, arg2: number) => void;
};
